DECLARE		@ST_S	DATETIME,
			@TS_S	DATETIME,
			@PR_S	DATETIME,
			@ROWS	INTEGER


SET @ST_S	= GETDATE()
SET @TS_S	= GETDATE()
SET @PR_S	= GETDATE()
SET @ROWS   = 0

EXEC STAGING.LOG_EVENT 1, 2, 2, @ROWS, 'CLM FAC. Delete prior FAC information from CLAIMS_INVENTORY_LOAD table',	@ST_S,	@TS_S, @PR_S

TRUNCATE TABLE [REPORTS].[CLAIMS_INVENTORY_LOAD]
